import sys,csv,argparse

def run(argv):
    p=argparse.ArgumentParser(prog='xan sort')
    p.add_argument('-d','--delimiter');p.add_argument('-n','--no-headers',action='store_true');p.add_argument('-o','--output');p.add_argument('-s','--select');p.add_argument('-N','--numeric',action='store_true');p.add_argument('-R','--reverse',action='store_true');p.add_argument('-u','--uniq',action='store_true');p.add_argument('-c','--count');p.add_argument('--check',action='store_true');p.add_argument('--columns',action='store_true');p.add_argument('--cells',action='store_true');p.add_argument('-U','--unstable',action='store_true');p.add_argument('-p','--parallel',action='store_true');p.add_argument('-e','--external',action='store_true');p.add_argument('input',nargs='?')
    a=p.parse_args(argv)
    if a.count and not a.uniq: raise ValueError('-c/--count can only be used with -u/--uniq!')
    if a.delimiter is None:
        ext=(a.input or '').lower().removesuffix('.gz').rsplit('.',1)[-1]
        a.delimiter={'tsv':'\t','tab':'\t','psv':'|','ssv':';','scsv':';','cdx':' '}.get(ext,',')
    if a.input and a.input!='-':
        if a.input.endswith('.gz'):
            import gzip
            f=gzip.open(a.input,'rt',encoding='utf-8-sig',newline='')
        else:f=open(a.input,encoding='utf-8-sig',newline='')
    else:f=sys.stdin
    rows=[r for r in csv.reader(f,delimiter=a.delimiter) if r]
    if f is not sys.stdin:f.close()
    rows=[r for r in rows if r]
    if not rows:return 0
    header=[] if a.no_headers else rows.pop(0)
    width=max([len(header)]+[len(r) for r in rows]) if rows else len(header)
    if a.no_headers: header=[str(i) for i in range(width)]
    rows=[r+['']*(width-len(r)) for r in rows]
    def colidx(token):
        if token in header:return header.index(token)
        try:
            i=int(token); return i+width if i<0 else i
        except ValueError: raise ValueError('unknown column: '+token)
    ix=(list(range(width)) if (a.columns or a.cells) else ([0] if width else [])) if not a.select else []
    if a.select:
        for tok in a.select.split(','):
            if ':' in tok:
                lo,hi=tok.split(':',1);x=colidx(lo) if lo else 0;y=colidx(hi) if hi else width-1;ix.extend(range(x,y+1))
            else:ix.append(colidx(tok))
    if a.columns:
        order=list(range(width))
        slots=sorted(set(ix))
        ordered=sorted(slots,key=lambda j:header[j],reverse=a.reverse)
        for pos,j in zip(slots,ordered): order[pos]=j
        header=[header[j] for j in order]
        rows=[[r[j] for j in order] for r in rows]
        result=([header] if not a.no_headers else [])+rows
    elif a.cells:
        for r in rows:
            vals=[r[j] for j in ix]
            if a.numeric:
                try: vals.sort(key=float,reverse=a.reverse)
                except ValueError:
                    print('xan sort: Could not parse cell as number!',file=sys.stderr)
                    return 1
            else: vals.sort(reverse=a.reverse)
            for j,v in zip(ix,vals): r[j]=v
        result=([header] if not a.no_headers else [])+rows
    else:
        def key(r):
            vals=[r[j] for j in ix]
            if not a.numeric: return tuple(vals)
            key=[]
            for x in vals:
                try: key.append((2,float(x)))
                except ValueError: key.append((1,0))
            return tuple(key)
        ordered=sorted(rows,key=key,reverse=a.reverse)
        if a.check:
            return 0 if ordered==rows else 1
        result=[]
        if a.count:
            if not a.no_headers: header=header+[a.count]
            counted=[]
            for r in ordered:
                k=key(r)
                if counted and counted[-1][0]==k: counted[-1][1]+=1
                else: counted.append([k,1,r])
            result=[r+[str(n)] for _,n,r in counted]
        elif a.uniq:
            prev=object()
            for r in ordered:
                k=key(r)
                if not result or k!=prev: result.append(r);prev=k
        else:result=ordered
        if not a.no_headers: result=[header]+result
    out=sys.stdout if not a.output else open(a.output,'w',encoding='utf-8',newline='')
    csv.writer(out,delimiter=a.delimiter,lineterminator='\n').writerows(result)
    if out is not sys.stdout:out.close()
    return 0

